REVOKE UPDATE ON public.tickets FROM authenticated;
GRANT UPDATE (reply, status) ON public.tickets TO authenticated;
CREATE OR REPLACE FUNCTION public.consume_search(p_sector text, p_city text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Login necessário'; END IF; IF length(trim(p_sector)) < 2 OR length(trim(p_city)) < 2 OR length(p_sector) > 80 OR length(p_city) > 80 THEN RAISE EXCEPTION 'Setor ou cidade inválidos'; END IF; INSERT INTO public.accounts(user_id) VALUES(auth.uid()) ON CONFLICT (user_id) DO NOTHING; UPDATE public.accounts SET credits = credits - 1 WHERE user_id = auth.uid() AND credits > 0; IF NOT FOUND THEN RAISE EXCEPTION 'Créditos insuficientes'; END IF; INSERT INTO public.searches(user_id, sector, city) VALUES(auth.uid(), trim(p_sector), trim(p_city)) RETURNING id INTO v_id; RETURN v_id; END $$;